"""Write the permission bitfield as TypeScript for the frontend (ADR-017 contract style)."""

import json
from pathlib import Path
from typing import Any

from django.core.management.base import BaseCommand

from apps.core.permissions import DEFAULT_EVERYONE, DESCRIPTIONS, Perm

HEADER = """/**
 * Generated by `python manage.py export_permissions`. Do not edit.
 * Source of truth: backend/apps/core/permissions.py (docs/DATA_MODEL.md#permissions).
 */
"""


def render() -> str:
    lines = [HEADER, "export const Perm = {"]
    lines += [f"  {p.name}: {int(p)}," for p in Perm]
    lines += ["} as const;", "", "export type PermName = keyof typeof Perm;", ""]
    lines += ["export const PERMISSION_DESCRIPTIONS: Record<PermName, string> = {"]
    lines += [f"  {p.name}: {json.dumps(DESCRIPTIONS[p])}," for p in Perm]
    lines += ["};", "", f"export const DEFAULT_EVERYONE = {int(DEFAULT_EVERYONE)};", ""]
    return "\n".join(lines)


class Command(BaseCommand):
    help = "Export permission bits to a TypeScript module."

    def add_arguments(self, parser: Any) -> None:
        parser.add_argument("output", help="Path of the .ts file to write")

    def handle(self, *args: Any, **options: Any) -> None:
        Path(options["output"]).write_text(render())
        self.stdout.write(f"wrote {options['output']}")
